"""Preserve mathematical controls and later findings at an explicit partial checkpoint."""
import hashlib,json,pathlib
H=pathlib.Path(__file__).resolve().parent;P='additional_pfp_infrastructure_remaining';f=json.loads((H/(P+'_preparation.json')).read_text())['files'];rp=H/(P+'.json');r=json.loads(rp.read_text())
def ev(i,a,b):return {'path':f[i]['path'],'sha256':f[i]['sha256'],'lines':[a,b]}
rows=[
('019','Exception type alone mislabels a downstream failure as preflight','TracedGateway treats every listed gate exception escaping complete as undispatched. A synthetic downstream gateway that records dispatch then raises the same listed exception produces a preflight dispatched=False receipt. This type-based inference does not establish when failure occurred.',[ev(273,102,129),ev(270,502,524)],['PFPINFRA-P025'],'Use an explicit admission/dispatch phase marker or typed outcome whose provenance is established at the admission boundary.'),
('020','Workflow replay skips missing provider wire and ignores its internal hash','For provider records, _wire_matches_response returns True if raw_reply_base64 is absent; when present it compares only decoded content, not raw_reply_sha256. File manifests bind bytes but cannot substitute for validating internal provider evidence relations.',[ev(278,231,247),ev(278,456,472)],['PFPINFRA-P026','PFPINFRA-P027'],'Require complete provider evidence on accounted records, verify exact raw hash and independently replay accounting bindings when billing verification is claimed.'),
('021','Four central rational solver methods use an undefined variable','compute_gamma2, compute_phi1, verify_duality_gap and compute_hodge_decomposition accept omega but read core.values. No core binding exists in the module. All four valid-shape calls raise NameError before returning the stated mathematical result.',[ev(158,57,116),ev(158,135,180),ev(158,227,327)],['PFPINFRA-P028'],'Repair the parameter references in a separate authorized change and then test actual domain DTO/caller paths; current rational method claims are not executable.'),
('022','Dense diagnostic can pass an incorrect ground multiplicity','For the admitted-style two-qubit Pauli penalty H with exact diagonal[0,10^15,1,10^15+1], true ground multiplicity is1. Relative noise floor1000 merges the eigenvalue1 with ground and returns PASSED for claimed multiplicity2. SECONDARY_NUMERIC labeling limits its authority but does not make the agreement correct.',[ev(235,105,143)],['PFPINFRA-P031'],'Return inconclusive when near-ground separation is unresolved at scale; use an exact certificate for multiplicity and preserve numeric evidence limits.'),
('023','Silent catalog fallback changes operational metadata','Neighboring taxonomy registries silently skip malformed rows and fallback. Execution-mode fallback marks live labels is_live=False; evaluation fallback marks NOT_RUN terminal and ACCEPTED invalid. Import-time Enum/VALID snapshots can also diverge from later mutable registrations. Task-family loader is a useful strict exception.',[ev(260,84,106),ev(259,86,107),ev(262,22,40)],[],'Fail explicitly on resource corruption or provide semantically identical pinned fallback; avoid treating vocabulary metadata as enforcement.'),
('024','Tribunal receipt hash omits verdicts and gate-set completeness','Tribunal accepts caller attestations honestly labeled AttestedPass, but all([]) passes when no recognized gates load. Its receipt hash binds candidate/all_passed/status/count, not the gate IDs, individual outcomes or evidence. Distinct gate records can therefore share that summary digest.',[ev(161,243,277)],[],'Require the exact declared gate set and hash canonical full verdict/evidence bindings; retain AttestedPass wording.'),
('025','Round gates do not enforce their declared evidence set','Round1 accepts an unrelated missing element, round2 accepts an unrelated declared element and float50.0, and round6 accepts quote empty-string plus reason banana. These checks enforce selected labels/substrings, not required carrier/measure declarations or reason relevance.',[ev(220,147,161),ev(220,228,269),ev(220,365,393)],['PFPINFRA-P032','PFPINFRA-P033','PFPINFRA-P034'],'Validate exact required declaration keys and nonempty source quotes; separate lexical screening from semantic entailment and mathematical evidence.'),
('026','Symbolic expression adapter lacks an admitted grammar and execution bounds','_parse forwards arbitrary strings to SymPy parse_expr with local symbols but no restricted global environment, AST allowlist, byte bound or execution timeout. The callable helpers differentiate/integrate/simplify these strings. Dynamic parser-surface control could not run because SymPy is absent in both available interpreters.',[ev(218,93,116),ev(218,134,162)],['PFPINFRA-P035'],'Define and enforce a restricted symbolic grammar and resource limits before accepting candidate expressions; preserve domain/branch assumptions. Dynamic safety result remains unverified.'),
]
items={x['id']:x for x in r['findings']}
for id,title,detail,refs,probes,action in rows:items['PFPINFRA-F'+id]={'id':'PFPINFRA-F'+id,'severity':'high'if id=='021'else'medium','title':title,'finding':detail,'evidence':refs,'probes':probes,'next_action':action,'status':'open','scope':'Identified source boundary only; bounded controls and source interpretation are distinguished from fresh end-to-end execution.'}
r['findings']=list(items.values());claims={x['id']:x for x in r['claims']}
claims['PFPINFRA-C008']={'id':'PFPINFRA-C008','claim':'Integer SNF and cycle membership have concrete exact operations and replay obligations: U*A*V=D, diagonal divisibility, and reconstructed integer boundary preimage. Bounded independent controls matched invariant factors for625 small2x2 matrices.','evidence':[ev(158,346,515),ev(158,517,714)],'dependencies':['Exact integer matrix carrier/shape validation','Unimodular operation invariant','Declared chain complex and integer coefficients'],'limitations':['625 matrices do not prove all dimensions or universal termination.10000 reductions per pivot is a resource refusal. Topological meaning is admitted via supplied matrices; beta path supplies a boundary by construction.']}
claims['PFPINFRA-C009']={'id':'PFPINFRA-C009','claim':'Standalone L1 certificate checking provides a sufficient conditional optimum certificate: actual alpha residual, dual annihilation, infinity capacity<=1 and primal=dual imply optimum by weak duality. Residual and reported value are replayed exactly.','evidence':[ev(158,720,844)],'dependencies':['Finite rational matrix/vector carrier','Supplied unweighted L1 objective','Exact input shape and rational semantics'],'limitations':['Positive triangle plus tampered-value controls are bounded. This is not the broken class compute_phi1 path, a physical encoding theorem, or an efficiency claim.']}
claims['PFPINFRA-C010']={'id':'PFPINFRA-C010','claim':'Several retained demo adapters explicitly limit their evidence: MSSN suite is inventory plus two host controls and two mutations; retired aggregate fails with unmet obligations; Demo004 claims only one source-bound NO_LLM control.','evidence':[ev(225,23,75),ev(222,13,57),ev(217,16,54)],'dependencies':['Actual delegated witness/child checkers'],'limitations':['No demo execution in this slice, no fifty-task/provider efficacy or retired aggregate completion. Other suites still have broader titles than their few fixed checks.']}
r['claims']=list(claims.values());v={x['path']:x for x in r['validation']}
for suffix,count,reproduced in [('04',3,3),('05',4,4),('06',4,3)]:
 vp=P+'_checks'+suffix+'.json';b=(H/vp).read_bytes();j=json.loads(b);v[vp]={'path':vp,'sha256':hashlib.sha256(b).hexdigest(),'controls':count,'reproduced':reproduced,'not_run':count-reproduced,'python':j['python'],'scope':j['method']}
r['validation']=list(v.values());r['validation_environment_limits']=['.venv Python3.14.2 lacks numpy, so checks05 initially failed import; existing uv Python3.12.12 ran all four checks05 controls with numpy.','SymPy absent in .venv3.14.2 and uv3.12.12; checks06 ran three standard-library gate controls and recorded P035 not_run. No dependency install or download.'];ctx=P+'_consulted_context.json';r['related_context']=[{'path':'dag/reviews/'+ctx,'sha256':hashlib.sha256((H/ctx).read_bytes()).hexdigest(),'use':'Exact consulted domain Hamiltonian review row preserved; context only, no new coverage credit.'}];rp.write_text(json.dumps(r,indent=2)+'\n')
(H/(P+'.md')).write_text(f"# PFP infrastructure audit — in progress\n\n{r['full_source_read_count']}/{r['scope_count']} frozen files have complete substantive body reviews; {len(r['remaining_work'])} remain. No parsing-only reading credit.\n\nThe report has {len(r['claims'])} synthesis claims and {len(r['findings'])} findings. Four rational solver methods fail on undefined core; normal-form route maps admit recomputation/escalation; selected demos accept asserted verifier flags. Recovery/custody controls expose V1 path traversal, incomplete request identities and missing provider-wire binding. A scaled two-qubit numeric control passes an incorrect ground multiplicity.\n\nPositive mechanisms include declared-FD scope in the SQL pipeline, exact finite sum checking, rational L1 zero-gap certificate replay, integer SNF with625 independent small-matrix controls, strict trace bytes/seals and response replay. These remain conditional, finite mechanisms rather than general physical or provider-effectiveness evidence.\n\n34 controls reproduced; one parser control was not run because SymPy is unavailable. NumPy controls used existing Python3.12.12 after the task .venv lacked NumPy. No installs, providers, native builds, original edits or private benchmark reads. Exact paths/hashes/ranges, outcomes and pending scope remain in JSON.\n")
print(json.dumps({'full':r['full_source_read_count'],'remaining':len(r['remaining_work']),'claims':len(r['claims']),'findings':len(r['findings']),'reproduced_controls':34,'not_run':1}))
